import type { Context } from "@earendil-works/chord";

// Sidecar -> host loopback client. The host token is generated by server/app.py
// at sidecar startup and passed only through the process environment; it is
// never stored in a transcript or shown to the model.
export interface HostConfig {
	readonly url: string;
	readonly token: string;
}

export class HostUnavailableError extends Error {}

export function hostConfig(env = process.env): HostConfig | undefined {
	const url = (env.XIAOXI_HOST_URL ?? "").trim().replace(/\/+$/, "");
	const token = (env.XIAOXI_HOST_TOKEN ?? "").trim();
	if (url === "" || token === "") return undefined;
	return { url, token };
}

const HOST_TIMEOUT_MS = 10_000;

function abortSignal(context: Context): AbortSignal {
	const timeout = AbortSignal.timeout(HOST_TIMEOUT_MS);
	if (context.abortSignal === undefined) return timeout;
	return AbortSignal.any([context.abortSignal, timeout]);
}

export async function hostJson(
	path: string,
	init: { method?: "GET" | "POST"; body?: unknown } = {},
	context?: Context,
): Promise<unknown> {
	const config = hostConfig();
	if (config === undefined) {
		throw new HostUnavailableError("宿主只读接口未配置（XIAOXI_HOST_URL / XIAOXI_HOST_TOKEN 缺失）");
	}
	const headers: Record<string, string> = { authorization: `Bearer ${config.token}` };
	if (init.body !== undefined) headers["content-type"] = "application/json";
	const response = await fetch(`${config.url}${path}`, {
		method: init.method ?? "GET",
		headers,
		body: init.body === undefined ? undefined : JSON.stringify(init.body),
		signal: context === undefined ? AbortSignal.timeout(HOST_TIMEOUT_MS) : abortSignal(context),
	});
	const text = await response.text();
	let payload: unknown = text;
	try {
		payload = text === "" ? {} : JSON.parse(text);
	} catch {
		// Keep the text for diagnostics; the caller decides whether it is usable.
	}
	if (!response.ok) {
		const detail = typeof payload === "string" ? payload : JSON.stringify(payload);
		throw new Error(`宿主接口 ${path} 返回 ${response.status}：${detail.slice(0, 300)}`);
	}
	return payload;
}

export function asText(value: unknown, limit = 12_000): string {
	const text = typeof value === "string" ? value : JSON.stringify(value, null, 2);
	return text.length > limit ? `${text.slice(0, limit)}\n\n[已截断]` : text;
}
